void PluginMain(PA_long32 selector, PA_PluginParameters params)
{
	try
	{
		PA_long32 pProcNum = selector;
		sLONG_PTR *pResult = (sLONG_PTR *)params->fResult;
		PackagePtr pParams = (PackagePtr)params->fParameters;

		CommandDispatcher(pProcNum, pResult, pParams); 
	}
	catch(...)
	{

	}
}

void CommandDispatcher (PA_long32 pProcNum, sLONG_PTR *pResult, PackagePtr pParams)
{
	switch(pProcNum)
	{
// --- Hash

		case 1 :
			Generate_checksum(pResult, pParams);
			break;

	}
}

// ------------------------------------- Hash -------------------------------------

bool Execute_method(size_t pos, size_t total, method_id_t methodId, const PA_Unichar *methodName)
{
	bool shouldAbort = false;
	
	if(methodId)
	{
		PA_Variable	params[2];
		params[0] = PA_CreateVariable(eVK_Real);
		params[1] = PA_CreateVariable(eVK_Real);
		PA_SetRealVariable(&params[0], pos);
		PA_SetRealVariable(&params[1], total);
		
		PA_Variable result = PA_ExecuteMethodByID(methodId, params, 2);
		
		if(PA_GetVariableKind(result) == eVK_Boolean)
			shouldAbort = PA_GetBooleanVariable(result);

		/* the method may return text, blob, picture, etc. */
		PA_ClearVariable(&result);
		PA_ClearVariable(&params[0]);
		PA_ClearVariable(&params[1]);
	}else
	
	if(methodName)
	{
		PA_Variable	params[4];
		/* PA_SetStringVariable is shallow: eVK_Unistring would leak an empty string */
		params[0] = PA_CreateVariable(eVK_Undefined);
		PA_Unistring _methodName = PA_CreateUnistring((PA_Unichar *)methodName);
		PA_SetStringVariable(&params[0], &_methodName);
		params[1] = PA_CreateVariable(eVK_Boolean);
		PA_SetBooleanVariable(&params[1], shouldAbort);
		params[2] = PA_CreateVariable(eVK_Real);
		params[3] = PA_CreateVariable(eVK_Real);
		PA_SetRealVariable(&params[2], pos);
		PA_SetRealVariable(&params[3], total);
		PA_ExecuteCommandByID(1007, params, 4);
		shouldAbort = PA_GetBooleanVariable(params[1]);
		PA_ClearVariable(&params[0]);
		PA_ClearVariable(&params[1]);
		PA_ClearVariable(&params[2]);
		PA_ClearVariable(&params[3]);
	}
	
	return shouldAbort;
}

void Generate_checksum(sLONG_PTR *pResult, PackagePtr pParams)
{
	C_TEXT Param1;
	C_LONGINT Param2;
	C_LONGINT Param3;
	C_TEXT Param4;
	C_TEXT returnValue;

	Param1.fromParamAtIndex(pParams, 1);
	Param2.fromParamAtIndex(pParams, 2);
	Param3.fromParamAtIndex(pParams, 3);
	Param4.fromParamAtIndex(pParams, 4);

#if VERSIONMAC
	Param1.convertPath();
	CUTF8String path;
	Param1.copyUTF8String(&path);
#else
	CUTF16String path;
	Param1.copyUTF16String(&path);
#endif
	
	unsigned int type = Param2.getIntValue();
	const EVP_MD *evp;

	switch (type)
	{
  case Checksum_SHA1:
			evp = EVP_sha1();
			break;
  case Checksum_SHA256:
			evp = EVP_sha256();
			break;
  case Checksum_SHA384:
			evp = EVP_sha384();
			break;
  case Checksum_SHA512:
			evp = EVP_sha512();
			break;
  default:
			evp = EVP_md5();
			break;
	}
	
	unsigned int format = Param3.getIntValue();
	const PA_Unichar *methodName = Param4.getUTF16Length() ? Param4.getUTF16StringPtr() : NULL;
	method_id_t methodId = PA_GetMethodID((PA_Unichar *)Param4.getUTF16StringPtr());
	
	/* stat before fopen: fopen blocks on a fifo, and a device never reaches EOF */
#if VERSIONMAC
	struct stat st;
	bool isFile = (stat((const char *)path.c_str(), &st) == 0) && S_ISREG(st.st_mode);
#else
	struct _stat64 st;
	bool isFile = (_wstat64((const wchar_t *)path.c_str(), &st) == 0) && ((st.st_mode & _S_IFMT) == _S_IFREG);
#endif

	FILE *f = NULL;

	if(isFile)
	{
#if VERSIONMAC
		f = fopen ((const char *)path.c_str(), "rb");
#else
		f = _wfopen ((const wchar_t *)path.c_str(), L"rb");
#endif
	}

	if(f)
	{
		/* st_size is 64-bit on both platforms; ftell returns a 32-bit long on Windows */
		size_t total = (size_t)st.st_size;
		size_t pos = 0;
		size_t len;

		unsigned char *buf = (unsigned char *)malloc(BUFFER_SIZE);
		EVP_MD_CTX* c = EVP_MD_CTX_create();

		if((buf) && (c) && (EVP_DigestInit_ex(c, evp, NULL)))
		{
			unsigned int mdlen = 0;
			bool aborted = false;
			bool failed = false;

			/* call the progress method at most every CALLBACK_INTERVAL_MS, not on every read */
			std::chrono::steady_clock::time_point lastCallback = std::chrono::steady_clock::now();
			size_t lastCallbackPos = 0;

			while ((len = fread (buf, 1, BUFFER_SIZE, f)) != 0)
			{
				PA_YieldAbsolute();
				if(!EVP_DigestUpdate(c, buf, len))
				{
					failed = true;
					break;
				}
				pos += len;

				std::chrono::steady_clock::time_point now = std::chrono::steady_clock::now();
				if((now - lastCallback) >= std::chrono::milliseconds(CALLBACK_INTERVAL_MS))
				{
					lastCallback = now;
					lastCallbackPos = pos;
					aborted = Execute_method(pos, total, methodId, methodName);

					if(aborted)
						break;
				}
			}

			/* fread returns 0 on error as well as EOF; don't return a digest of partial data */
			if(ferror(f))
				failed = true;

			/* always report completion */
			if((!aborted) && (!failed) && (pos != lastCallbackPos))
				aborted = Execute_method(pos, total, methodId, methodName);

			if((!aborted) && (!failed))
			{
				unsigned char md[EVP_MAX_MD_SIZE];

				if(EVP_DigestFinal_ex(c, md, &mdlen))
				{
					C_BLOB temp;
					temp.setBytes((const uint8_t *)md, mdlen);
					switch (format)
					{
						case Checksum_Format_Base64:
							temp.toB64Text(&returnValue);
							break;
						default:
							temp.toHexText(&returnValue);
							break;
					}
				}
			}
		}

		/* EVP_MD_CTX_destroy also cleans up the digest state when aborted */
		if(c)
			EVP_MD_CTX_destroy(c);

		if(buf)
			free(buf);

		fclose(f);
	}
	
	returnValue.setReturn(pResult);
}

